import { FormSection, PageHeader, StickyActionBar, ValidationSummary } from '@gntik-ai/blocks';
import {
  Checkbox,
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
  Input,
  Page,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  Stack,
  Textarea,
  type BreadcrumbItem,
} from '@gntik-ai/ui';
import { useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  FIELD_IDS,
  formBreadcrumbs,
  formInitialValues,
  formRegions,
  validateResourceForm,
  type RegionOption,
  type ResourceFormValues,
} from './data';

export interface ResourceFormProps {
  title: string;
  description: string;
  breadcrumbs: BreadcrumbItem[];
  initialValues: ResourceFormValues;
  regions: readonly RegionOption[];
  /** Called with valid values; return a promise to show the saving state until it settles. */
  onSubmit: (values: ResourceFormValues) => void | Promise<void>;
  /** Discard: called after the form is reset to its initial values. */
  onCancel: () => void;
  shell: Omit<ConsoleShellProps, 'children'>;
}

const same = (a: ResourceFormValues, b: ResourceFormValues) =>
  a.name === b.name && a.description === b.description && a.region === b.region && a.billingEmail === b.billingEmail && a.sendInvoices === b.sendInvoices;

/** Edit (or create) form: two-column FormSections, an error summary after submit, and a sticky save bar. */
export default function ResourceFormPage({
  title = 'Edit project',
  description = 'Details, region and billing for billing-dashboard.',
  breadcrumbs = formBreadcrumbs,
  initialValues = formInitialValues,
  regions = formRegions,
  onSubmit,
  onCancel,
  shell,
}: Partial<ResourceFormProps>) {
  const [baseline, setBaseline] = useState(initialValues);
  const [values, setValues] = useState(initialValues);
  const [submitCount, setSubmitCount] = useState(0);
  const [saving, setSaving] = useState(false);
  const errors = submitCount > 0 ? validateResourceForm(values) : [];
  const errorFor = (fieldId: string) => errors.find((e) => e.fieldId === fieldId)?.message;
  const set = <K extends keyof ResourceFormValues>(key: K, value: ResourceFormValues[K]) => setValues((v) => ({ ...v, [key]: value }));

  const save = async () => {
    setSubmitCount((n) => n + 1);
    if (validateResourceForm(values).length > 0) return;
    setSaving(true);
    try {
      await onSubmit?.(values);
      setBaseline(values);
      setSubmitCount(0);
    } finally {
      setSaving(false);
    }
  };

  const nameError = errorFor(FIELD_IDS.name);
  const regionError = errorFor(FIELD_IDS.region);
  const emailError = errorFor(FIELD_IDS.billingEmail);

  return (
    <ConsoleShell currentHref="/projects" breadcrumbs={breadcrumbs} {...shell}>
      <Page header={<PageHeader breadcrumbs={null} title={title} description={description} status="" meta={[]} actions={[]} tabs={null} />}>
        <form
          noValidate
          aria-label={title}
          onSubmit={(e) => {
            e.preventDefault();
            void save();
          }}
        >
          <Stack gap={8}>
            <ValidationSummary errors={errors} submitCount={submitCount} />
            <FormSection title="General" description="Basic details shown to everyone who can access this project.">
              <Stack gap={4}>
                <Field invalid={nameError != null}>
                  <FieldLabel required>Project name</FieldLabel>
                  <Input id={FIELD_IDS.name} required value={values.name} onValueChange={(v) => set('name', v)} />
                  <FieldDescription>Lowercase letters, numbers and dashes.</FieldDescription>
                  <FieldError match={nameError != null}>{nameError}</FieldError>
                </Field>
                <Field>
                  <FieldLabel>Description</FieldLabel>
                  <Textarea rows={3} value={values.description} onValueChange={(v) => set('description', v)} />
                </Field>
              </Stack>
            </FormSection>
            <FormSection divided title="Region" description="Where the project's services run. It cannot be changed later.">
              <Field invalid={regionError != null}>
                <FieldLabel required>Region</FieldLabel>
                <Select value={values.region || null} onValueChange={(v) => set('region', v ?? '')} items={regions.map(({ value, label }) => ({ value, label }))}>
                  <SelectTrigger id={FIELD_IDS.region} className="w-full sm:max-w-sm" placeholder="Choose a region" />
                  <SelectContent>
                    {regions.map((r) => (
                      <SelectItem key={r.value} value={r.value}>
                        {r.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FieldError match={regionError != null}>{regionError}</FieldError>
              </Field>
            </FormSection>
            <FormSection divided title="Billing" description="Who receives invoices and usage alerts for this project.">
              <Stack gap={4}>
                <Field invalid={emailError != null}>
                  <FieldLabel required>Billing email</FieldLabel>
                  <Input id={FIELD_IDS.billingEmail} type="email" required value={values.billingEmail} onValueChange={(v) => set('billingEmail', v)} />
                  <FieldError match={emailError != null}>{emailError}</FieldError>
                </Field>
                <Checkbox
                  label="Email invoices to this address"
                  description="A PDF copy is sent on the first day of each month."
                  checked={values.sendInvoices}
                  onCheckedChange={(checked) => set('sendInvoices', checked)}
                />
              </Stack>
            </FormSection>
            <StickyActionBar
              dirty={!same(values, baseline)}
              saving={saving}
              onSave={() => void save()}
              onCancel={() => {
                setValues(baseline);
                setSubmitCount(0);
                onCancel?.();
              }}
            />
          </Stack>
        </form>
      </Page>
    </ConsoleShell>
  );
}

import type { ValidationIssue } from '@gntik-ai/blocks';
import type { BreadcrumbItem } from '@gntik-ai/ui';

export interface ResourceFormValues {
  name: string;
  description: string;
  region: string;
  billingEmail: string;
  sendInvoices: boolean;
}

export interface RegionOption {
  value: string;
  label: string;
}

export const formBreadcrumbs: BreadcrumbItem[] = [
  { label: 'Projects', href: '/projects' },
  { label: 'billing-dashboard', href: '#billing-dashboard', mono: true },
  { label: 'Edit' },
];

export const formRegions: RegionOption[] = [
  { value: 'eu-west-1', label: 'EU West · Ireland' },
  { value: 'eu-central-1', label: 'EU Central · Frankfurt' },
  { value: 'us-east-1', label: 'US East · Virginia' },
  { value: 'ap-south-1', label: 'Asia Pacific · Mumbai' },
];

/** The saved project being edited. */
export const formInitialValues: ResourceFormValues = {
  name: 'billing-dashboard',
  description: 'Usage and invoice reporting for every workspace.',
  region: 'eu-west-1',
  billingEmail: 'billing@example.com',
  sendInvoices: true,
};

/** Ids of the controls, the targets of the ValidationSummary links. */
export const FIELD_IDS = { name: 'project-name', region: 'region', billingEmail: 'billing-email' } as const;

const NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Validates the form; the order matches the visual order of the fields. */
export function validateResourceForm(v: ResourceFormValues): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  if (!v.name.trim()) issues.push({ fieldId: FIELD_IDS.name, label: 'Project name', message: 'Enter a project name.' });
  else if (!NAME_RE.test(v.name)) issues.push({ fieldId: FIELD_IDS.name, label: 'Project name', message: 'Use lowercase letters, numbers and dashes.' });
  if (!v.region) issues.push({ fieldId: FIELD_IDS.region, label: 'Region', message: 'Choose a region.' });
  if (!EMAIL_RE.test(v.billingEmail)) issues.push({ fieldId: FIELD_IDS.billingEmail, label: 'Billing email', message: 'Enter a valid email address, like name@company.com.' });
  return issues;
}

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
